$ErrorActionPreference='Stop'
$root=$PSScriptRoot;$name='Trajectory-ObservableInformation-Step3-20261027'
function Read-Json($relative){$p=Join-Path $root $relative;if(Test-Path -LiteralPath $p){Get-Content -LiteralPath $p -Raw -Encoding UTF8|ConvertFrom-Json}else{$null}}
$processes=@(Get-CimInstance Win32_Process -Filter "Name='python.exe'"|Where-Object{$_.CommandLine -and $_.CommandLine.IndexOf($root,[StringComparison]::OrdinalIgnoreCase) -ge 0}|ForEach-Object{[pscustomobject]@{pid=$_.ProcessId;parent=$_.ParentProcessId;created=$_.CreationDate.ToString('o');commandline=$_.CommandLine}})
$parents=@($processes.parent|Sort-Object -Unique|ForEach-Object{Get-CimInstance Win32_Process -Filter "ProcessId=$_"|Select-Object ProcessId,ParentProcessId,Name,CommandLine})
$task=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
$triggers=$null;if($task){[xml]$xml=Export-ScheduledTask -TaskName $name;$triggers=@($xml.SelectNodes('/*[local-name()="Task"]/*[local-name()="Triggers"]/*')).Count}
$histories=@();if(Test-Path -LiteralPath (Join-Path $root 'runs')){Get-ChildItem -LiteralPath (Join-Path $root 'runs') -Directory|ForEach-Object{$h=Join-Path $_.FullName 'history.json';if(Test-Path -LiteralPath $h){$x=Get-Content -LiteralPath $h -Raw -Encoding UTF8|ConvertFrom-Json;$histories+=[pscustomobject]@{run=$_.Name;updates=@($x).Count;done=(Test-Path -LiteralPath (Join-Path $_.FullName 'done.json'))}}}}
[pscustomobject]@{at=(Get-Date).ToString('o');task=$name;task_state=if($task){[string]$task.State}else{$null};triggers=$triggers;processes=$processes;parents=$parents;worker=(Read-Json 'worker_state.json');exit=(Read-Json 'exit_status.json');stage=(Read-Json 'progress.json');child=(Read-Json 'current_child.json');histories=$histories;result=(Read-Json 'RESULT.json');stderr_bytes=if(Test-Path -LiteralPath (Join-Path $root 'worker.stderr.log')){(Get-Item -LiteralPath (Join-Path $root 'worker.stderr.log')).Length}else{$null}}|ConvertTo-Json -Depth 30
